// Package manifest records files generated by devlog-learn so pruning can
// remove only unchanged files owned by this tool.
package manifest

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// SchemaVersion covers the manifest JSON shape.
const SchemaVersion = 1

// FileName is the manifest stored at the output root.
const FileName = ".devlog-manifest.json"

// FileRecord describes one generated output file.
type FileRecord struct {
	DocID       string    `json:"doc_id,omitempty"`
	Profile     string    `json:"profile"`
	SHA256      string    `json:"sha256"`
	Size        int64     `json:"size"`
	GeneratedAt time.Time `json:"generated_at"`
}

// GeneratedFile identifies a file written by one generator profile.
type GeneratedFile struct {
	Path  string
	DocID string
}

// Manifest is the persisted ownership record for one output directory.
type Manifest struct {
	SchemaVersion int                   `json:"schema_version"`
	GeneratedAt   time.Time             `json:"generated_at"`
	Files         map[string]FileRecord `json:"files"`
}

// Report describes what Reconcile removed or deliberately left in place.
type Report struct {
	Pruned   int
	Skipped  int
	Deleted  []string
	Kept     []string
	Warnings []string
}

// Reconcile updates the manifest for one profile. When prune is true, old
// files from the same profile are removed only if their current hash still
// matches the manifest. Unregistered and modified files are never deleted.
func Reconcile(outDir, profile string, files []GeneratedFile, prune bool, now time.Time) (Report, error) {
	var report Report
	outDir = strings.TrimSpace(outDir)
	profile = strings.TrimSpace(profile)
	if outDir == "" {
		return report, errors.New("output directory must not be empty")
	}
	if profile == "" {
		return report, errors.New("manifest profile must not be empty")
	}
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return report, fmt.Errorf("create output directory: %w", err)
	}
	outDir, err := canonicalRoot(outDir)
	if err != nil {
		return report, err
	}

	current := make(map[string]GeneratedFile, len(files))
	for _, file := range files {
		rel, err := normalizeRelative(file.Path)
		if err != nil {
			report.Warnings = append(report.Warnings, fmt.Sprintf("ignore manifest path %q: %v", file.Path, err))
			continue
		}
		file.Path = rel
		current[rel] = file
	}

	existing := newManifest(now)
	loaded, err := Load(outDir)
	switch {
	case err == nil:
		existing = loaded
	case errors.Is(err, os.ErrNotExist):
	case err != nil:
		report.Warnings = append(report.Warnings,
			fmt.Sprintf("manifest could not be trusted; pruning skipped: %v", err))
		prune = false
	}

	for rel, record := range existing.Files {
		if record.Profile != profile || current[rel].Path != "" {
			continue
		}
		if !prune {
			continue
		}
		removed, retainRecord, warning := removeIfUnchanged(outDir, rel, record)
		switch {
		case warning != "":
			report.Skipped++
			report.Kept = append(report.Kept, rel)
			report.Warnings = append(report.Warnings, warning)
		case removed:
			report.Pruned++
			report.Deleted = append(report.Deleted, rel)
		}
		if !retainRecord {
			delete(existing.Files, rel)
		}
	}

	for rel, file := range current {
		record, warning := hashGenerated(outDir, rel, file, profile, now)
		if warning != "" {
			report.Skipped++
			report.Warnings = append(report.Warnings, warning)
			continue
		}
		existing.Files[rel] = record
	}
	existing.SchemaVersion = SchemaVersion
	existing.GeneratedAt = now.UTC()
	if existing.Files == nil {
		existing.Files = map[string]FileRecord{}
	}
	if err := save(outDir, existing); err != nil {
		return report, err
	}
	return report, nil
}

// Load reads the manifest from outDir.
func Load(outDir string) (*Manifest, error) {
	path := filepath.Join(outDir, FileName)
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var value Manifest
	if err := json.Unmarshal(data, &value); err != nil {
		return nil, fmt.Errorf("decode %s: %w", path, err)
	}
	if value.SchemaVersion != SchemaVersion {
		return nil, fmt.Errorf("unsupported manifest schema %d in %s", value.SchemaVersion, path)
	}
	if value.Files == nil {
		value.Files = map[string]FileRecord{}
	}
	return &value, nil
}

func newManifest(now time.Time) *Manifest {
	return &Manifest{
		SchemaVersion: SchemaVersion,
		GeneratedAt:   now.UTC(),
		Files:         map[string]FileRecord{},
	}
}

func hashGenerated(outDir, rel string, file GeneratedFile, profile string, now time.Time) (FileRecord, string) {
	path, err := resolve(outDir, rel)
	if err != nil {
		return FileRecord{}, fmt.Sprintf("skip manifest entry %q: %v", rel, err)
	}
	info, err := os.Lstat(path)
	if err != nil {
		return FileRecord{}, fmt.Sprintf("skip manifest entry %q: %v", rel, err)
	}
	if !info.Mode().IsRegular() {
		return FileRecord{}, fmt.Sprintf("skip manifest entry %q: not a regular file", rel)
	}
	sum, err := fileSHA256(path)
	if err != nil {
		return FileRecord{}, fmt.Sprintf("hash generated file %q: %v", rel, err)
	}
	docID := strings.TrimSpace(file.DocID)
	return FileRecord{
		DocID:       docID,
		Profile:     profile,
		SHA256:      sum,
		Size:        info.Size(),
		GeneratedAt: now.UTC(),
	}, ""
}

func removeIfUnchanged(outDir, rel string, record FileRecord) (removed bool, retainRecord bool, warning string) {
	path, err := resolve(outDir, rel)
	if err != nil {
		return false, false, fmt.Sprintf("skip pruning %q: %v", rel, err)
	}
	info, err := os.Lstat(path)
	if errors.Is(err, os.ErrNotExist) {
		return false, false, ""
	}
	if err != nil {
		return false, true, fmt.Sprintf("skip pruning %q: %v", rel, err)
	}
	if !info.Mode().IsRegular() {
		return false, false, fmt.Sprintf("kept %q: not a regular file", rel)
	}
	sum, err := fileSHA256(path)
	if err != nil {
		return false, true, fmt.Sprintf("skip pruning %q: %v", rel, err)
	}
	if record.SHA256 == "" || sum != record.SHA256 {
		return false, false, fmt.Sprintf("kept %q: generated file was modified", rel)
	}
	if err := os.Remove(path); err != nil {
		return false, true, fmt.Sprintf("remove stale generated file %q: %v", rel, err)
	}
	return true, false, ""
}

func normalizeRelative(value string) (string, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", errors.New("path is empty")
	}
	if filepath.IsAbs(value) {
		return "", errors.New("absolute paths are not allowed")
	}
	clean := filepath.Clean(filepath.FromSlash(value))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", errors.New("path escapes the output directory")
	}
	if filepath.VolumeName(clean) != "" {
		return "", errors.New("volume-qualified paths are not allowed")
	}
	return filepath.ToSlash(clean), nil
}

func resolve(outDir, rel string) (string, error) {
	normalized, err := normalizeRelative(rel)
	if err != nil {
		return "", err
	}
	current := outDir
	parts := strings.Split(normalized, "/")
	for index, part := range parts {
		current = filepath.Join(current, filepath.FromSlash(part))
		info, statErr := os.Lstat(current)
		if errors.Is(statErr, os.ErrNotExist) {
			break
		}
		if statErr != nil {
			return "", statErr
		}
		if info.Mode()&os.ModeSymlink != 0 {
			escaped := strings.Join(parts[:index+1], "/")
			return "", fmt.Errorf("path %q traverses a symbolic link", escaped)
		}
	}
	return current, nil
}

func canonicalRoot(outDir string) (string, error) {
	absolute, err := filepath.Abs(outDir)
	if err != nil {
		return "", fmt.Errorf("resolve output directory: %w", err)
	}
	return absolute, nil
}

func fileSHA256(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

func save(outDir string, value *Manifest) error {
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return fmt.Errorf("encode manifest: %w", err)
	}
	data = append(data, '\n')
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return fmt.Errorf("create output directory: %w", err)
	}
	path := filepath.Join(outDir, FileName)
	tmp, err := os.CreateTemp(outDir, ".devlog-manifest-*.tmp")
	if err != nil {
		return fmt.Errorf("create manifest temp file: %w", err)
	}
	tmpPath := tmp.Name()
	removeTemp := true
	defer func() {
		if removeTemp {
			_ = os.Remove(tmpPath)
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write manifest: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("sync manifest: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close manifest: %w", err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		return fmt.Errorf("replace manifest: %w", err)
	}
	removeTemp = false
	return nil
}
